def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            if opp.get('budget', 0) >= 900:
                if bid is not None and float(bid) >= 90:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    units = supply / WATER_REQ
    tight = units < 2.0
    medium_tight = units < 2.5

    sorted_bids = sorted(prev_bids) if prev_bids else []
    highest_prev = sorted_bids[-1] if sorted_bids else 0.0
    second_prev = sorted_bids[-2] if len(sorted_bids) >= 2 else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if tight:
        urgency += 2
    elif medium_tight:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 7:
        target = max(highest_prev + 2.5, 0.92 * DAILY_SALARY)
    elif urgency >= 5:
        target = max(second_prev + 2.0, 0.78 * DAILY_SALARY)
    elif urgency >= 3:
        target = max(0.58 * DAILY_SALARY, min(highest_prev + 1.0, 0.88 * DAILY_SALARY))
    else:
        if highest_prev >= 120:
            target = 22.0 if not tight else 48.0
        elif highest_prev >= 90:
            target = 26.0 if not tight else 52.0
        elif highest_prev >= 60:
            target = 34.0 if not tight else 56.0
        else:
            target = max(28.0, highest_prev + 1.5)

    if rich_aggressive >= 2 and hp >= 5 and no_water == 0 and not tight:
        target *= 0.8

    if day >= 8:
        target *= 1.12
    if budget < 140:
        target = min(target, 0.72 * DAILY_SALARY)
    if budget < 80:
        target = min(target, 0.55 * DAILY_SALARY)

    target = max(0.0, min(budget, target))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate trace only
    prev_bids = []
    prev_hp = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        try:
            prev_hp.append(int(prev.get('hp_after', o.get('hp', 0))))
        except Exception:
            prev_hp.append(int(o.get('hp', 0)))

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding very high, we need to secure water but avoid overpaying.
        # Cindy bid ~101 and Alex ~98 previously; use those as cues.
        pressure = highest_prev_bid / float(DAILY_SALARY)
    else:
        highest_prev_bid = 0.0
        pressure = 0.0

    # Estimate how many water units are likely available (supply is total; bids compete for allocation)
    # Use supply bands to adjust aggressiveness.
    supply_band = 0
    if supply <= float(MIN_SUPPLY) + 0.5:
        supply_band = 0  # tight
    elif supply >= float(MAX_SUPPLY) - 0.5:
        supply_band = 2  # ample
    else:
        supply_band = 1  # medium

    # Base bid depends on our urgency
    if my_hp <= 2 or my_no_water_days >= 2:
        urgency_mult = 1.0
    elif my_hp <= 4:
        urgency_mult = 0.85
    else:
        urgency_mult = 0.65

    # Aggressiveness based on yesterday's highest bid and supply tightness
    if pressure >= 1.0:
        # Opponents were spending heavily yesterday; match slightly below top to win often.
        target = highest_prev_bid * (0.92 if supply_band == 0 else 0.88)
    elif pressure >= 0.85:
        target = max(DAILY_SALARY * 0.55, highest_prev_bid * (0.9 if supply_band == 0 else 0.85))
    else:
        target = DAILY_SALARY * (0.48 if supply_band == 2 else 0.62)

    target *= urgency_mult

    # Cap to preserve budget for later days
    # Keep some reserve: if budget is low, bid closer to budget.
    reserve_fraction = 0.25 if my_budget >= DAILY_SALARY * 2 else 0.15
    max_affordable = my_budget * (1.0 - reserve_fraction)

    # Ensure at least a minimal competitive bid when supply is tight
    min_competitive = DAILY_SALARY * (0.35 if supply_band == 2 else 0.55)

    bid = float(target)
    if bid < min_competitive and supply_band != 2:
        bid = min_competitive

    bid = min(bid, max_affordable, my_budget)
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        bid = min(my_status['budget'], avg_prev * 1.05)
    else:
        bid = min(my_status['budget'], DAILY_SALARY * 0.8)

    if my_status['hp'] < 4:
        return min(my_status['budget'], bid * 1.2)
    return min(my_status['budget'], bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for op in alive_opponents:
        trace = op.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if hp <= 0:
        return budget if budget > 0 else 0

    if hp <= 2:
        urgency = 0.9
    elif hp <= 4:
        urgency = 0.6
    else:
        urgency = 0.3

    base_bid = DAILY_SALARY * urgency
    if supply < 18:
        base_bid *= 1.3
    elif supply > 22:
        base_bid *= 0.8

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > base_bid and hp <= 3:
            base_bid = max_prev + 1.0
        elif max_prev < base_bid and hp > 4:
            base_bid = max_prev * 0.9

    bid = min(budget, max(1, base_bid))
    return bid
